import copy
import json
from taf.ul.oam_kpi_calculations.alarm import Alarm
from taf.ul.oam_kpi_calculations.utilities import custom_json_serializable


class AlarmEventDetection(object):
    def __init__(self):
        self.all_alarm_events = []
        self.active_alarms = []
        self._detected_alarm_events = {}

    def mark_alarm_as_set(self, alarm_dist_name, timestamp, details):
        alarm_obj = self._create_alarm_from_raw_value(details)
        alarm_obj.alarm_set_timestamp = timestamp
        self._detected_alarm_events[alarm_dist_name] = {
            'alarm': alarm_obj,
            'details': details,
        }
        if alarm_obj not in self.active_alarms:
            self.active_alarms.append(alarm_obj)

    def mark_alarm_as_removed(self, alarm_dist_name, timestamp):
        if alarm_dist_name not in self._detected_alarm_events:
            self._detected_alarm_events[alarm_dist_name] = {
                'removed_timestamp': timestamp
            }
        else:
            if 'alarm' in self._detected_alarm_events[alarm_dist_name]:
                self._detected_alarm_events[alarm_dist_name]['alarm'].alarm_removed_timestamp = timestamp
        try:
            self.active_alarms.remove(self._detected_alarm_events[alarm_dist_name]['alarm'])
        except (KeyError, ValueError):
            pass

    def clear_variables(self):
        self.all_alarm_events = []
        self.active_alarms = []
        self._detected_alarm_events = {}

    def reset_detected_alarm_events(self, reset_type, timestamp):
        self.all_alarm_events.append(self._detected_alarm_events)
        self.all_alarm_events.append({'type': reset_type, 'timestamp': timestamp})
        self.active_alarms = []
        self._detected_alarm_events = {}

    def move_detected_alarms_to_all_alarm_events(self):
        self.all_alarm_events.append(self._detected_alarm_events)
        self._detected_alarm_events = {}

    def alarm_is_active(self, alarm):
        if alarm in self.active_alarms:
            return True
        return False

    def save_all_alarm_events_to_file(self, file_path):
        with open(file_path, 'w') as f:
            f.write(json.dumps(self.all_alarm_events, indent=4, sort_keys=True, default=custom_json_serializable))

    @staticmethod
    def is_alarm_in_time_range(start, end, alarm):
        if start is None and end is None:
            return True
        elif start is None and alarm.alarm_set_timestamp <= end:
            return True
        elif end is None and (alarm.alarm_removed_timestamp is None or alarm.alarm_removed_timestamp >= start):
            return True
        elif start and end and alarm.alarm_set_timestamp <= end and \
                (alarm.alarm_removed_timestamp is None or alarm.alarm_removed_timestamp >= start):
            return True
        return False

    def get_active_alarms_from_time_range(self, start=None, end=None):
        alarms = []
        filtered_detected_alarm_events = copy.copy(self._detected_alarm_events)
        for alarm_dist_name in self._detected_alarm_events:
            if 'alarm' not in self._detected_alarm_events[alarm_dist_name]:
                del filtered_detected_alarm_events[alarm_dist_name]
        items = list(filtered_detected_alarm_events.items())
        items.sort(key=lambda i: i[1]['alarm'].alarm_set_timestamp)
        for dist_name, alarm_event in items:
            alarm = alarm_event['alarm']
            if self.is_alarm_in_time_range(start, end, alarm):
                alarms.append(alarm)
        return alarms

    def verify_allowed_alarms(self, allowed_alarms, start=None, end=None):
        # TODO in next release - verify allowed alarms in passed time range. If alarm other than allowed
        #  is visible then raise Exception
        pass

    def verify_required_alarms(self, mandatory_alarms, start=None, end=None):
        # TODO in next release - verify required alarms in passed time range. If one of mandatory alarm not exists
        #  then raise Exception
        pass

    def load_results_from_file(self, file_path):
        # TODO in next release - load file and then could be used offline to check if some alarm exists
        #  in passed time range
        pass

    @staticmethod
    def _create_alarm_from_raw_value(raw_value):
        raw_value = raw_value.get('alarmInformation', raw_value)
        return Alarm(
            alarm_number=raw_value.get('alarmNumber'),
            alarm_name=raw_value.get('alarmName'),
            alarm_severity=raw_value.get('alarmSeverity'),
            alarming_resource_dist_name=raw_value.get('alarmingResourceDN'),
            alarm_detail=raw_value.get('alarmText')['alarmDetail'],
            fault_name=raw_value.get('alarmText')['faultDescription'],
            fault_id=raw_value.get('faultId'),
            fault_severity=raw_value.get('faultSeverity'),
        )
